result.text:
  border-top: 2px solid var(--line-2, #cfcfcf);
  border-bottom: 2px solid var(--line-2, #cfcfcf);
  background: var(--surface-2, #f6f5f2);
}

.acc-warn {
  margin-top: 12px;
  padding: 12px 14px;
  border-radius: 10px;
  background: #fdf4e3;
  border: 1px solid #f0dcb4;
  color: #6b4d10;
  font-size: 13px;
  line-height: 1.45;
}

.acc-warn strong { display: block; margin-bottom: 3px; }
.acc-warn .btn { margin-top: 9px; }

@media (max-width: 620px) {
  .acc-tabs { gap: 5px; }
  .acc-tab { padding: 5px 10px; font-size: 12px; }
  .acc-table .acc-label { white-space: normal; }
  .acc-warn { font-size: 12.5px; }
  .acc-toolbar-note { flex-wrap: wrap; }
  .acc-toolbar-note .btn { margin-left: 0; }
}
